/* Echappement HTML, audit securite du 01/10/2026. Toute valeur saisie par le visiteur passe par esc avant d entrer dans le HTML du mail. */
const esc = (s) => String(s).replace(/[&<>"']/g, (ch) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const b = $input.first().json.body ?? {};
const r = b.resultat ?? {};
const euros = (n) => new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Math.round(n||0));
/* Mensualite unique depuis le 02/10/2026, decision d Adib. Une brique n a plus de prix de chantier ni de suivi separe, elle a une mensualite, construction et surveillance comprises. Le site envoie mensualite, mensualitePleine, gainMensuel et gainNetPerimetre. L ancienne forme, coutChantier, suiviMensuel et roiMois, reste lue le temps du deploiement, pour qu une estimation partie de l ancien site recoive encore un mail juste. */
const nouveau = typeof r.mensualite === 'number';
/* Le diagnostic est offert des que l estimation est positive, au moins une tache qui rend plus que sa mensualite. Le mail ne le dit que dans ce cas. */
const positive = nouveau && (r.recommandees ?? []).length > 0 && !r.aucunRetour && !r.sousLePlancher;
const td = 'padding:10px 12px;border-bottom:1px solid #e3f7ef;';
const lignes = (r.recommandees ?? []).map((l,i)=>'<tr><td style="'+td+'">'+(i+1)+'. '+esc(l.label)+'</td><td style="'+td+'text-align:right;white-space:nowrap;">'+(nouveau ? euros(l.mensualite)+' par mois' : euros(l.cout))+'</td></tr>').join('');
const chiffres = nouveau
 ? '<p style="margin:0 0 6px;">Mensualité estimée <strong>' + euros(r.mensualite) + '</strong> hors taxes, construction et surveillance comprises. Vous ne payez rien d\'avance pour la construction.</p>'
   + '<p style="margin:0 0 6px;">Ces tâches vous rendent environ <strong>' + euros(r.gainMensuel) + '</strong> de temps par mois. Il vous reste <strong>' + euros(r.gainNetPerimetre) + ' par mois</strong>, mensualité payée, dès qu\'elles tournent.</p>'
   + '<p style="margin:0 0 22px;">Chaque tâche engage douze mois. Ensuite vous arrêtez avec trente jours de préavis.</p>'
 : '<p style="margin:0 0 6px;">Chantier estimé <strong>' + euros(r.coutChantier) + '</strong> hors taxes.</p>'
   + '<p style="margin:0 0 6px;">Suivi mensuel <strong>' + euros(r.suiviMensuel) + '</strong> hors taxes pour ce périmètre.</p>'
   + '<p style="margin:0 0 22px;">Retour sur investissement estimé, <strong>' + r.roiMois + ' mois</strong>, une fois le suivi payé.</p>';
const html = '<!doctype html><html lang="fr"><head><meta charset="utf-8"></head><body style="margin:0;background:#ffffff;color:#1f2222;font-family:Helvetica,Arial,sans-serif;font-size:15px;line-height:1.6;"><div style="max-width:560px;margin:0 auto;padding:28px 22px;">'
 + '<p style="font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#5c6462;margin:0 0 14px;">Odegia</p>'
 + '<h1 style="font-size:24px;line-height:1.2;margin:0 0 18px;">' + (b.prenom ? esc(b.prenom) + ', votre' : 'Votre') + ' estimation</h1>'
 + '<p style="margin:0 0 16px;">Votre administratif représente environ <strong>' + (r.heuresMois||0).toFixed(1).replace('.',',') + ' heures par mois</strong>, soit <strong>' + euros(r.coutAnnuel) + ' par an</strong> au taux horaire que vous avez indiqué.</p>'
 + '<div style="background:#e3f7ef;border:2px solid #1f2222;border-radius:14px;padding:16px 18px;margin:0 0 20px;"><p style="margin:0 0 8px;"><strong>Ces chiffres sont un ordre de grandeur.</strong> Ils viennent de moyennes appliquées à vos réponses, sur des barèmes que nous affinons encore.</p><p style="margin:0;font-size:13.5px;color:#5c6462;">Le diagnostic approfondi mesure vos volumes réels, tâche par tâche, et remet un rapport et une feuille de route datée. C\'est lui qui sert de base au devis.' + (positive ? ' Votre estimation est positive, il vous est donc offert.' : '') + '</p></div>'
 + '<h2 style="font-size:17px;margin:0 0 10px;">Par où nous commencerions</h2><table style="width:100%;border-collapse:collapse;margin:0 0 18px;">' + lignes + '</table>'
 + chiffres
 + '<p style="margin:0 0 22px;"><a href="https://calendar.app.google/znA8TAyk56TiRcGA6" style="display:inline-block;background:#0f7a5c;color:#ffffff;text-decoration:none;padding:12px 22px;border-radius:999px;">Réserver quinze minutes</a></p>'
 + '<p style="font-size:12px;color:#5c6462;margin:0;border-top:1px solid #e3f7ef;padding-top:14px;">Odegia, marque d\'Orbis Optima Group. Vous recevez cet email parce que vous avez demandé une estimation sur odegia.com. Écrivez à contact@odegia.com pour toute demande de suppression.</p>'
 + '</div></body></html>';
// Le cout mensuel est calcule ici et non dans le modele Brevo, qui ne sait
// pas faire d arithmetique sur un attribut de contact.
const coutMensuel = Math.round((r.coutAnnuel || 0) / 12);
// Toutes les colonnes de la table NocoDB sortent d ici, y compris celles
// qui ne servent pas a l email. Un seul endroit a maintenir.
// Depuis la mensualite unique, la colonne suivi_mensuel porte la mensualite,
// cout_chantier vaut zero et roi_mois aussi, il n y a plus de chantier a
// rembourser. Les noms de colonnes n ont pas change pour ne pas toucher aux
// noeuds NocoDB et Brevo.
return [{ json: {
  email: b.email,
  prenom: b.prenom || '',
  optin: b.optinProspection === true,
  recuLe: b.recuLe || '',
  heuresMois: Math.round((r.heuresMois || 0) * 10) / 10,
  coutAnnuel: Math.round(r.coutAnnuel || 0),
  coutMensuel,
  coutChantier: nouveau ? 0 : Math.round(r.coutChantier || 0),
  suiviMensuel: Math.round((nouveau ? r.mensualite : r.suiviMensuel) || 0),
  roiMois: nouveau ? 0 : r.roiMois,
  nbBriques: (r.recommandees ?? []).length,
  taches: (b.reponses?.taches ?? []).join(', '),
  taux: r.taux,
  html,
} }];
